BEGIN;

CREATE TABLE rol (
    "id_rol" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre_rol" VARCHAR(80) NOT NULL,
    "descripcion_rol" TEXT,
    PRIMARY KEY ("id_rol")
);

CREATE TABLE tipo_usuario (
    "id_tipo_usuario" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre_tipo_usuario" VARCHAR(100) NOT NULL,
    "descripcion_tipo" TEXT,
    PRIMARY KEY ("id_tipo_usuario")
);

CREATE TABLE perfil (
    "id_perfil" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "area_estudio" VARCHAR(150),
    "biografia_corta" TEXT,
    "fecha_actualizacion" TIMESTAMP,
    PRIMARY KEY ("id_perfil")
);

CREATE TABLE tipo_servicio (
    "id_tipo_servicio" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre_tipo_servicio" VARCHAR(100) NOT NULL,
    "descripcion_categoria" TEXT,
    PRIMARY KEY ("id_tipo_servicio")
);

CREATE TABLE tipo_producto (
    "id_tipo_producto" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre_tipo_producto" VARCHAR(100) NOT NULL,
    "descripcion_categoria" TEXT,
    PRIMARY KEY ("id_tipo_producto")
);

CREATE TABLE tipo_evento (
    "id_tipo_evento" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre_tipo_evento" VARCHAR(100) NOT NULL,
    "descripcion_tipo" TEXT,
    PRIMARY KEY ("id_tipo_evento")
);

CREATE TABLE usuario (
    "id_usuario" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_rol" INTEGER,
    "id_tipo_usuario" INTEGER,
    "id_perfil" INTEGER,
    "nombres" VARCHAR(100) NOT NULL,
    "apellidos" VARCHAR(100) NOT NULL,
    "correo_institucional" VARCHAR(150) NOT NULL,
    "clave_hash" TEXT NOT NULL,
    "fecha_registro" TIMESTAMP,
    "estado_usuario" VARCHAR(30),
    PRIMARY KEY ("id_usuario"),
    FOREIGN KEY ("id_rol") REFERENCES rol(id_rol) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_tipo_usuario") REFERENCES tipo_usuario(id_tipo_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_perfil") REFERENCES perfil(id_perfil) ON UPDATE CASCADE ON DELETE RESTRICT,
    UNIQUE ("correo_institucional")
);

CREATE TABLE publicacion (
    "id_publicacion" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_usuario_autor" INTEGER,
    "titulo_publicacion" VARCHAR(200),
    "contenido_publicacion" TEXT,
    "fecha_publicacion" TIMESTAMP,
    "estado_publicacion" VARCHAR(30),
    PRIMARY KEY ("id_publicacion"),
    FOREIGN KEY ("id_usuario_autor") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE comentario (
    "id_comentario" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_publicacion" INTEGER,
    "id_usuario_comentador" INTEGER,
    "texto_comentario" TEXT,
    "fecha_comentario" TIMESTAMP,
    PRIMARY KEY ("id_comentario"),
    FOREIGN KEY ("id_publicacion") REFERENCES publicacion(id_publicacion) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_usuario_comentador") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE grupo (
    "id_grupo" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_usuario_creador" INTEGER,
    "id_perfil" INTEGER,
    "nombre_grupo" VARCHAR(150),
    "descripcion_grupo" TEXT,
    "fecha_creacion" DATE,
    PRIMARY KEY ("id_grupo"),
    FOREIGN KEY ("id_usuario_creador") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_perfil") REFERENCES perfil(id_perfil) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE servicio (
    "id_servicio" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_usuario_ofertante" INTEGER,
    "id_tipo_servicio" INTEGER,
    "titulo_servicio" VARCHAR(200),
    "descripcion_servicio" TEXT,
    "precio" NUMERIC(12,2),
    "duracion_estimada" VARCHAR(100),
    "ubicacion" VARCHAR(30),
    "estado_servicio" VARCHAR(30),
    PRIMARY KEY ("id_servicio"),
    FOREIGN KEY ("id_usuario_ofertante") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_tipo_servicio") REFERENCES tipo_servicio(id_tipo_servicio) ON UPDATE CASCADE ON DELETE RESTRICT,
    CHECK (precio IS NULL OR precio >= 0)
);

CREATE TABLE producto (
    "id_producto" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_usuario_vendedor" INTEGER,
    "id_tipo_producto" INTEGER,
    "nombre_producto" VARCHAR(200),
    "descripcion_producto" TEXT,
    "precio_producto" NUMERIC(12,2),
    "estado_producto" VARCHAR(30),
    "fecha_publicacion" TIMESTAMP,
    PRIMARY KEY ("id_producto"),
    FOREIGN KEY ("id_usuario_vendedor") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_tipo_producto") REFERENCES tipo_producto(id_tipo_producto) ON UPDATE CASCADE ON DELETE RESTRICT,
    CHECK (precio_producto IS NULL OR precio_producto >= 0)
);

CREATE TABLE evento (
    "id_evento" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_usuario_organizador" INTEGER,
    "id_tipo_evento" INTEGER,
    "titulo_evento" VARCHAR(200),
    "descripcion_evento" TEXT,
    "fecha_hora_inicio" TIMESTAMP,
    "fecha_hora_fin" TIMESTAMP,
    "lugar_evento" VARCHAR(200),
    "cupo_maximo" INTEGER,
    PRIMARY KEY ("id_evento"),
    FOREIGN KEY ("id_usuario_organizador") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_tipo_evento") REFERENCES tipo_evento(id_tipo_evento) ON UPDATE CASCADE ON DELETE RESTRICT,
    CHECK (fecha_hora_fin IS NULL OR fecha_hora_inicio IS NULL OR fecha_hora_fin >= fecha_hora_inicio)
);

CREATE TABLE notificacion (
    "id_notificacion" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_usuario" INTEGER,
    "titulo_notificacion" VARCHAR(200),
    "mensaje_notificacion" TEXT,
    "tipo_notificacion" VARCHAR(50),
    "estado_lectura" VARCHAR(20),
    "fecha_envio" TIMESTAMP,
    PRIMARY KEY ("id_notificacion"),
    FOREIGN KEY ("id_usuario") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE mensaje (
    "id_mensaje" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_emisor" INTEGER,
    "id_receptor" INTEGER,
    "contenido_mensaje" TEXT,
    "fecha_hora_envio" TIMESTAMP,
    "estado_mensaje" VARCHAR(20),
    PRIMARY KEY ("id_mensaje"),
    FOREIGN KEY ("id_emisor") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_receptor") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE valoracion (
    "id_valoracion" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_usuario_evaluador" INTEGER,
    "id_servicio" INTEGER NOT NULL,
    "id_producto" INTEGER NOT NULL,
    "puntuacion" SMALLINT,
    "comentario_resena" TEXT,
    "fecha_valoracion" TIMESTAMP,
    PRIMARY KEY ("id_valoracion"),
    FOREIGN KEY ("id_usuario_evaluador") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_servicio") REFERENCES servicio(id_servicio) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_producto") REFERENCES producto(id_producto) ON UPDATE CASCADE ON DELETE RESTRICT,
    CHECK (puntuacion BETWEEN 1 AND 5),
    CHECK (id_servicio IS NOT NULL OR id_producto IS NOT NULL)
);

CREATE TABLE reaccion (
    "id_reaccion" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_usuario" INTEGER,
    "id_publicacion" INTEGER,
    "tipo_reaccion" VARCHAR(30),
    "fecha_reaccion" TIMESTAMP,
    PRIMARY KEY ("id_reaccion"),
    FOREIGN KEY ("id_usuario") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_publicacion") REFERENCES publicacion(id_publicacion) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE conexion (
    "id_conexion" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_usuario_solicitante" INTEGER,
    "id_usuario_receptor" INTEGER,
    "estado_conexion" VARCHAR(30),
    "fecha_solicitud" TIMESTAMP,
    "fecha_respuesta" TIMESTAMP,
    PRIMARY KEY ("id_conexion"),
    FOREIGN KEY ("id_usuario_solicitante") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_usuario_receptor") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE miembro_grupo (
    "id_usuario" INTEGER,
    "id_grupo" INTEGER,
    "rol_en_grupo" VARCHAR(30),
    "fecha_ingreso" DATE,
    PRIMARY KEY ("id_usuario", "id_grupo"),
    FOREIGN KEY ("id_usuario") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_grupo") REFERENCES grupo(id_grupo) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE solicitud_servicio (
    "id_usuario_solicitante" INTEGER,
    "id_servicio" INTEGER,
    "fecha_solicitud" TIMESTAMP,
    "estado_solicitud" VARCHAR(30),
    PRIMARY KEY ("id_usuario_solicitante", "id_servicio"),
    FOREIGN KEY ("id_usuario_solicitante") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_servicio") REFERENCES servicio(id_servicio) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE compra_producto (
    "id_usuario_comprador" INTEGER,
    "id_producto" INTEGER,
    "fecha_compra" TIMESTAMP,
    "cantidad" INTEGER,
    PRIMARY KEY ("id_usuario_comprador", "id_producto"),
    FOREIGN KEY ("id_usuario_comprador") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_producto") REFERENCES producto(id_producto) ON UPDATE CASCADE ON DELETE RESTRICT,
    CHECK (cantidad > 0)
);

CREATE TABLE asistencia_evento (
    "id_usuario" INTEGER,
    "id_evento" INTEGER,
    "fecha_registro" TIMESTAMP,
    "estado_asistencia" VARCHAR(30),
    PRIMARY KEY ("id_usuario", "id_evento"),
    FOREIGN KEY ("id_usuario") REFERENCES usuario(id_usuario) ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("id_evento") REFERENCES evento(id_evento) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE perfil_habilidad (
    "id_perfil" INTEGER,
    "habilidad" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    PRIMARY KEY ("id_perfil", "habilidad"),
    FOREIGN KEY ("id_perfil") REFERENCES perfil(id_perfil) ON UPDATE CASCADE ON DELETE RESTRICT
);

